            score += (fitting_bins_count as f64).ln() * 55.0;
        }
    }

    // 5. Harmonic Consolidation:
    // Modulo-based alignment to reduce variance in remaining bin capacities
    let alignment = if post_residual % 25 == 0 { 120.0 } 
                    else if post_residual % 20 == 0 { 90.0 } 
                    else if post_residual % 10 == 0 { 60.0 } 
                    else if post_residual % 5 == 0 { 35.0 }
                    else { 0.0 };
    score -= alignment;

    // 6. Global Uniformity:
    let residual_deviation = (post - mean_residual).abs();
    score += (residual_deviation / capacity) * 210.0 * (0.5 + progress);

    // 7. Final-Phase Aggression:
    // Exponentially increase pressure to close bins as the stream reaches end
    if progress > 0.75 {
        score -= (capacity - post) * 6.5; 
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Core strategy: Optimize for deep packing (tight residuals) while controlling new bin growth.
    // Base score is weighted by the remaining capacity to encourage filling existing bins.
    let mut score = post * 2.85;

    // 1. Lookahead refinement: Prevent small-gap fragmentation by penalizing residuals 
    // that are slightly larger than the next item but too small for future utility.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post == n {
            score -= 480.0;
        } else if post < n {
            // Penalize blocking the next item harder as the stream progresses
            score += (n - post).powf(2.4) * 64.0 * (1.2 + progress);
        } else if post < (n + 15.0) {
            // Penalty for "near-miss" slots that create fragile slivers
            score += (16.0 - (post - n)) * 28.0;
        }
    }

    // 2. Adaptive New Bin Pressure:
    // Scale penalty based on total open bins and current residual mean to prevent proliferation.
    if is_new_bin {
        let scarcity_penalty = (open_bins_count as f64).powf(1.15) * 110.0;
        score += 190.0 + (progress * 420.0) + (mean_residual * 12.5) + (fitting_bins_count as f64 * 55.0) + scarcity_penalty;
    }

    // 3. Fragmentation Mitigation:
    // Target the "death-zone" of 3-14 units where items are rare but space is wasted.
    if post > 2.0 && post < 15.0 {
        score += 310.0 * (1.25 - (progress * 0.45));
    }

    // 4. Utilization Density:
    if !is_new_bin {
        let utilization = (capacity - bin_residual as f64) / capacity;
        score -= utilization * 260.0;

        // Reward high-density completion
        if post == 0.0 { score -= 280.0; } 
        else if post < 6.0 { score -= 135.0 * (1.0 - progress * 0.5); }
    }

    // 5. Harmonic Consolidation:
    // Favor residuals that align with common item size distributions (e.g., 25s, 50s).
    let alignment = if post_residual % 25 == 0 { 110.0 } 
                    else if post_residual % 10 == 0 { 55.0 } 
                    else if post_residual % 5 == 0 { 25.0 }
                    else { 0.0 };
    score -= alignment;

    // 6. Global Uniformity:
    // Keep bins close to the moving mean to prevent outlier "empty" or "full" clusters.
    let residual_deviation = (post - mean_residual).abs();
    score += (residual_deviation / capacity) * 210.0 * (0.8 + progress);

    // 7. Final-Phase Aggression:
    // In the last 15%, prioritize filling every remaining sliver regardless of uniformity.
    if progress > 0.85 {
        score -= (capacity - post) * 5.2; 
        score -= (fitting_bins_count as f64) * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base objective: Minimize post_residual with a slight bias toward tighter fits
    let mut score = post * 1.5;

    // 1. Enhanced Lookahead:
    // Reward perfect fits for the next item, and penalize creating "unusable" slivers
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (post - n).abs() < 0.5 {
            score -= 195.0; 
        } else if post < n && post > 2.0 {
            // Penalize small gaps that prevent the next item from fitting
            score += (n - post) * 12.0 * (1.0 + progress);
        } else if post > n && post < (n * 1.5) {
            // Slight preference for leaving just enough room for the next item
            score -= 15.0;
        }
    }

    // 2. Dynamic New Bin Pressure:
    // Heavily penalize opening new bins, scaling with progress and existing bin count.
    if is_new_bin {
        let scarcity_penalty = (open_bins_count as f64).ln() * 40.0;
        score += 95.0 + (progress * 130.0) + (mean_residual * 2.8) + (fitting_bins_count as f64 * 25.0) + scarcity_penalty;
    }

    // 3. Fragmentation Mitigation:
    // Small gaps are expensive. Penalize them unless they are zero.
    if post > 0.0 && post < 16.0 {
        score += 140.0 * (1.1 - (progress * 0.5));
    }

    // 4. Utilization Density & Flexibility:
    // Reward bins that are well-filled (low residual), but penalize choosing a bin
    // that is significantly worse than the average to keep bin states uniform.
    if !is_new_bin {
        let utilization = (capacity - bin_residual as f64) / capacity;
        score -= utilization * 110.0;

        // Reward bin completion (zero residual)
        if post == 0.0 {
            score -= 85.0;
        }

        // If many bins can fit this item, pick the one that leaves the smallest residual
        if fitting_bins_count > 2 {
            score += (fitting_bins_count as f64) * 8.0 * (1.0 - progress);
        }
    }

    // 5. Harmonic Consolidation:
    // Align residuals to common factors to increase future fit compatibility (e.g., 25, 20).
    let alignment = if post_residual % 25 == 0 { 40.0 } 
                    else if post_residual % 20 == 0 { 30.0 } 
                    else if post_residual % 10 == 0 { 15.0 } 
                    else { 0.0 };
    score -= alignment;

    // 6. Global Uniformity:
    // Penalize deviation from the global mean residual to avoid "outlier" bins
    let residual_deviation = (post - mean_residual).abs();
    score += (residual_deviation / capacity) * 60.0;

    // 7. Final-Phase Aggression:
    // As we approach the end, prioritize closure over perfect fitting
    if progress > 0.92 {
        score += post * 2.5; 
    }

    score
}
